namespace ghidra.graph.viewer.layout;

using ghidra.graph;
using ghidra.graph.viewer;
using ghidra.graph.viewer;
using ghidra.util.task;
using ghidra.util.task;

//@formatter:off
public class CalculateLayoutLocationsTask<V, E> : Task where V : VisualVertex where E : VisualEdge<V> {
//@formatter:on

	private VisualGraphLayout<V, E> layout;
	private VisualGraph<V, E> graph;

	private LayoutPositions<V, E> locations;

	public CalculateLayoutLocationsTask(VisualGraph<V, E> graph, VisualGraphLayout<V, E> layout) : base("Calculate Layout Locations", true, false, true, true)
    {
		this.graph = graph;
		this.layout = layout;
	}

	/* @Override */
	public void run(TaskMonitor monitor) {
		monitor.setMessage("Calculating layout locations...");

		locations = layout.calculateLocations(graph, monitor);
	}

	public LayoutPositions<V, E> getLocations() {
		return locations;
	}
}
